import { getTeam } from "@/lib/data";

/**
 * Team icon.
 *
 * The artwork in /public/images/teams is generated by scripts/gen-team-icons.mjs:
 * original rounded-square badges (club colour gradient + abstract geometric
 * watermark + three-letter code). They are not reproductions of NBA or club
 * marks — the site previously shipped real club logos and received a DMCA
 * notice that explicitly listed "all associated team logos".
 */
export function TeamLogo({
  slug,
  size = 24,
  className = "",
}: {
  slug: string;
  size?: number;
  className?: string;
}) {
  const team = getTeam(slug);
  if (!team) return null;
  return (
    // eslint-disable-next-line @next/next/no-img-element
    <img
      src={`/images/teams/${team.slug}.png`}
      alt={`${team.name} icon`}
      width={size}
      height={size}
      loading="lazy"
      decoding="async"
      className={`inline-block shrink-0 rounded-[22%] object-contain ${className}`}
      style={{ width: size, height: size }}
    />
  );
}
